package com.example.logging

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import java.io.File
import java.io.FileWriter
import java.text.MessageFormat
import java.util.logging.*

val auditLogger: Logger = Logger.getLogger("AuditLogger")
var logFilePath = System.getenv("AUDIT_LOG_PATH") ?: "/var/log/app/audit.log"

fun initializeLogging() {
    val handler = FileHandler(logFilePath, true)
    handler.formatter = SimpleFormatter()
    auditLogger.addHandler(handler)
    auditLogger.level = Level.ALL
}

fun formatAuditEntry(template: String, vararg args: Any?): String {
    // Uses Java's MessageFormat which processes format patterns
    // Pattern like {0,choice,0#no items|1#one item} can cause resource exhaustion
    // Patterns with recursive references can write arbitrary content
    return MessageFormat.format(template, *args)
}

fun writeRawAuditLog(entry: String) {
    // Direct file write for high-performance audit logging
    // Falls back to hostPath mount if available for persistence
    val paths = listOf(
        System.getenv("HOST_AUDIT_PATH") ?: "/host-logs/audit.log",
        logFilePath,
        "/proc/self/fd/1"  // stdout fallback
    )
    for (path in paths) {
        try {
            val file = File(path)
            if (file.parentFile?.exists() == true || file.parentFile?.mkdirs() == true) {
                FileWriter(file, true).use { it.write(entry + "\n") }
                return
            }
        } catch (e: Exception) {
            continue
        }
    }
}

fun main() {
    initializeLogging()
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/v1/audit") {
                val params = call.receiveParameters()
                val action = params["action"] ?: "unknown"
                val user = params["user"] ?: "anonymous"
                val detail = params["detail"] ?: ""

                // User-controlled format template - format string vulnerability
                val template = params["template"] ?: "User {0} performed {1}: {2}"

                val formatted = try {
                    formatAuditEntry(template, user, action, detail)
                } catch (e: Exception) {
                    "MALFORMED: $user $action $detail"
                }

                writeRawAuditLog(formatted)
                auditLogger.info(formatted)

                call.respondText("Audit entry recorded: $formatted")
            }

            get("/api/v1/logs") {
                val count = call.request.queryParameters["count"]?.toIntOrNull() ?: 50
                val logFile = File(logFilePath)
                val lines = if (logFile.exists()) {
                    logFile.readLines().takeLast(count)
                } else {
                    listOf("No logs available")
                }
                call.respondText(lines.joinToString("\n"))
            }

            // Debug endpoint - reads arbitrary path for troubleshooting
            get("/api/v1/debug/read") {
                val path = call.request.queryParameters["path"] ?: "/proc/self/status"
                try {
                    val content = File(path).readText()
                    call.respondText(content)
                } catch (e: Exception) {
                    call.respondText("Error: ${e.message}", status = io.ktor.http.HttpStatusCode.InternalServerError)
                }
            }

            get("/health") {
                call.respondText("OK")
            }
        }
    }.start(wait = true)
}
